responseSchemaJson:
{
  "type": "object",
  "description": "角色更新大师的核心职责是将`<History>`中的新事件整合为一个单一、叙事流畅的记忆条目。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "generatedMemory": {
      "type": "object",
      "description": "[模块一：记忆生成] 包含生成的单一结构化新记忆数据。",
      "properties": {
        "characterName": {
          "type": "string",
          "description": "本次更新的目标角色中文名称：`{{源角色名称}}`。"
        },
        "updatedCharacterMemory": {
          "type": "object",
          "description": "一段全新的、以`{{源角色名称}}`第一人称视角叙述的增量记忆。",
          "properties": {
            "contextOrDate": {
              "type": "string",
              "description": "本次更新记忆的截止日期，格式必须为 'YYYY-MM-DD'。"
            },
            "entryDetail": {
              "type": "object",
              "description": "从`{{源角色名称}}`严格、客观的第一人称视角出发，对这一段剧情的结构化总结。**[指代规范]** 称呼自己必须用'我'；称呼他人**必须且仅能**使用**标准名称**。",
              "properties": {
                "details": {
                  "type": "string",
                  "description": "该剧情单元的**完整剧情实录**。**核心要求**：必须剔除所有文学修饰、微观动作、心理活动和环境描写。**只保留**核心事实、关键对话意图、达成的约定、做出的决策和事件因果。语言必须精炼、逻辑通顺。"
                },
                "summary": {
                  "type": "string",
                  "description": "基于上述实录提炼的**一段梗概**。只记录最重要的结果，**彻底舍弃**过程细节。"
                }
              },
              "required": [
                "details",
                "summary"
              ],
              "propertyOrdering": [
                "details",
                "summary"
              ]
            }
          },
          "required": [
            "contextOrDate",
            "entryDetail"
          ],
          "propertyOrdering": [
            "contextOrDate",
            "entryDetail"
          ]
        }
      },
      "required": [
        "characterName",
        "updatedCharacterMemory"
      ],
      "propertyOrdering": [
        "characterName",
        "updatedCharacterMemory"
      ]
    },
    "test": {
      "type": "object",
      "description": "[模块二：测试] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "generatedMemory",
    "test"
  ],
  "propertyOrdering": [
    "generatedMemory",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const data = JSON.parse(jsonString);
const mem = data.generatedMemory;
const ed = mem.updatedCharacterMemory.entryDetail;
const actions = [
    { type: 'description', content: `【角色更新目标】: ${mem.characterName}` },
    { type: 'description', content: `【新记忆】\n${ed.summary}\n详情:\n${ed.details}` }
];
return { processedTurnActions: actions, originalData: data };

